<?php
namespace App\Tests\Runtime;
use App\Runtime\{RuntimeEntityActionService,PermissionResolver};
use Doctrine\DBAL\DriverManager;
use PHPUnit\Framework\TestCase;
final class RuntimePurchaseOrderAttachmentLogScopeTest extends TestCase
{
 private function service($db):array{$r=new \ReflectionClass(RuntimeEntityActionService::class);$s=$r->newInstanceWithoutConstructor();$r->getProperty('connection')->setValue($s,$db);$p=$this->createStub(PermissionResolver::class);$p->method('getTenantId')->willReturn('a');$r->getProperty('permissions')->setValue($s,$p);return[$r,$s];}
 private function query($db,string $screen,?int $record=null,?string $operation=null):array{[$r,$s]=$this->service($db);$q=$db->createQueryBuilder()->select('t.id')->from('runtime_transaction_log','t')->orderBy('t.id');$scope=['audit_screen_id'=>$screen];if($record!==null)$scope['audit_record_id']=$record;if($operation!==null)$scope['audit_operation']=$operation;$r->getMethod('applyAuditLogScope')->invoke($s,$q,$scope);return array_map('intval',$q->executeQuery()->fetchFirstColumn());}
 private function db(){
  $db=DriverManager::getConnection(['driver'=>'pdo_sqlite','memory'=>true]);$db->executeStatement('CREATE TABLE runtime_transaction(id INTEGER,tenant_id TEXT,screen_id TEXT,status TEXT,operation TEXT,record_id TEXT)');$db->executeStatement('CREATE TABLE runtime_transaction_log(id INTEGER,transaction_id INTEGER,event_type TEXT,metadata TEXT)');
  $cases=['old-update','order-linked-update','order-root-create','order-root-delete','order-linked-delete','tenant','screen','failed','handler','available','source','version','typed-record','typed-item','typed-order','negative-item','null-item','overflow-item','overflow-order','resource','event','operation','old-zero'];
  foreach($cases as$i=>$case){$id=$i+1;$old=in_array($case,['old-update','old-zero'],true);$item=in_array($case,['order-root-create','order-root-delete','old-zero'],true)?0:11;$record=$item===0?102:101;$op=$case==='order-root-create'?'create':($case==='old-update'||$case==='order-linked-update'?'update':'delete');
   $audit=['available'=>true,'version'=>1,'source'=>'progress-transaction','resource'=>'anexos_proc_compra','operation'=>$op,'recordId'=>$record,'procCompraId'=>10,'itemProcCompraId'=>$item];$tx=['id'=>$id,'tenant_id'=>'a','screen_id'=>$old?'ciw.proc-compra-anexos':'ciw.proc-compra-documentos','status'=>'succeeded','operation'=>'entity.api.crud','record_id'=>(string)$record];$event=($old?'proc_compra_anexos_progress':'proc_compra_documentos_progress').'.api.'.$op;
   switch($case){case'tenant':$tx['tenant_id']='b';break;case'screen':$tx['screen_id']='other';break;case'failed':$tx['status']='failed';break;case'handler':$tx['operation']='delete';break;case'available':$audit['available']=false;break;case'source':$audit['source']='browser';break;case'version':$audit['version']='1';break;case'typed-record':$audit['recordId']='101';break;case'typed-item':$audit['itemProcCompraId']='11';break;case'typed-order':$audit['procCompraId']='10';break;case'negative-item':$audit['itemProcCompraId']=-1;break;case'null-item':$audit['itemProcCompraId']=null;break;case'overflow-item':$audit['itemProcCompraId']=2147483648;break;case'overflow-order':$audit['procCompraId']=2147483648;break;case'resource':$audit['resource']='envios_amostras_repres';break;case'event':$event='other.api.delete';break;case'operation':$audit['operation']='update';break;}
   $db->insert('runtime_transaction',$tx);$db->insert('runtime_transaction_log',['id'=>$id,'transaction_id'=>$id,'event_type'=>$event,'metadata'=>json_encode(['audit'=>$audit])]);
  }return$db;
 }
 public function testTwoRegisteredWritersShareTheHistoryOfTheSameLinkedRecord():void{$db=$this->db();foreach(['ciw.proc-compra-documentos','ciw.proc-compra-anexos']as$s){self::assertSame([1,2,5],$this->query($db,$s,101));self::assertSame([],$this->query($db,$s,999));}}
 public function testGeneralRecordIsNeverVisibleUnderItemAuditScope():void{$db=$this->db();self::assertSame([3,4],$this->query($db,'ciw.proc-compra-documentos',102));self::assertSame([],$this->query($db,'ciw.proc-compra-anexos',102));self::assertSame([1,2,5],$this->query($db,'ciw.proc-compra-itens',11));self::assertSame([1,2,3,4,5],$this->query($db,'ciw.processos-compra-med',10));self::assertSame([],$this->query($db,'ciw.processos-compra-med',20));}
 public function testDeletionScopesSelectOnlyMainDeletesOfTheirAllowedOwnership():void{$db=$this->db();self::assertSame([4,5],$this->query($db,'ciw.proc-compra-documentos',null,'delete'));self::assertSame([5],$this->query($db,'ciw.proc-compra-anexos',null,'delete'));self::assertSame([],$this->query($db,'ciw.proc-compra-itens',null,'delete'));}
 public function testPostgresStillRequiresTypedIdsClosedWritersTenantAndNativeHandler():void{$db=DriverManager::getConnection(['driver'=>'pdo_pgsql','serverVersion'=>'16.0']);[$r,$s]=$this->service($db);$q=$db->createQueryBuilder()->select('t.id')->from('runtime_transaction_log','t');$r->getMethod('applyAuditLogScope')->invoke($s,$q,['audit_screen_id'=>'ciw.proc-compra-documentos','audit_record_id'=>101]);$sql=$q->getSQL();foreach(["audit_scope.operation = 'entity.api.crud'","audit_scope.screen_id = 'ciw.proc-compra-documentos'","audit_scope.screen_id = 'ciw.proc-compra-anexos'","audit_scope.tenant_id = :sampleAuditTenant","audit_scope.status = 'succeeded'","'{audit,recordId}') = 'number'","'proc_compra_documentos_progress.api.'","2147483647"]as$guard)self::assertStringContainsString($guard,$sql);self::assertSame('a',$q->getParameter('sampleAuditTenant'));}
}
